ul.li:
          alone_or_singleline - The block comment end must be either
          alone on its own line or on the same line as the block comment begin.
          This allows multi-line Javadoc as well as single-line Javadoc comments:


// Block comment end is alone on its own line
/**
 * Multiple lines of Javadoc text are written here,
 * wrapped normally...
 */
public void method();

// Single-line Javadoc
/** Javadoc summary. */
public void method1();

pre.code:
/** Singleline Javadoc. */ // ok, 'alone_or_singleline' allows singleline Javadoc
class Example1 {

  /**
   * Invalid block comment end position. */
  int n = 10;
  // violation 2 lines above ''BLOCK_COMMENT_END' must be on the new line.'

  /**
   * Valid block comment end position.
   *
   * @param a the first number
   * @param b the second number
   * @return the sum of a and b
   */
  int add(int a, int b) {
    return a + b;
  }
}

/** Singleline Javadoc. */
class Example2 { // violation above ''BLOCK_COMMENT_END' must be on the new line.'

  /**
   * Invalid block comment end position. */
  int n = 10;
  // violation 2 lines above ''BLOCK_COMMENT_END' must be on the new line.'

  /**
   * Valid block comment end position.
   *
   * @param a the first number
   * @param b the second number
   * @return the sum of a and b
   */
  int add(int a, int b) {
    return a + b;
  }
}
